"""Validierte Geräte- und Verwaltungsaktionen."""from __future__ import annotationsimport timefrom typing import TYPE_CHECKINGfrom ..esp import FACESif TYPE_CHECKING:    from ..core import Coreasync def dispatch_action(    core: Core, intent: str, args: dict, session: str) -> tuple[dict, str, str]:    data, reply, status = {}, "Erledigt.", "completed"    if intent == "settings.save":        core.settings.write(core.settings.capture(core))        reply = "Einstellungen dauerhaft gespeichert; vorheriger Stand gesichert."    elif intent == "settings.restore":        if args["confirm"] is not True:            raise ValueError("Wiederherstellung ausdrücklich bestätigen.")        if core.audio.music_state != "STOPPED":            raise ValueError("Vor der Wiederherstellung Musik stoppen.")        value = (            core.default_settings            if args["source"] == "defaults"            else core.settings.read(args["source"])        )        await core.motion.stop()        core.settings.apply(core, value)        reply = "Einstellungen wiederhergestellt. Bewegung bleibt bis zur bewussten Freigabe gestoppt. Zum dauerhaften Übernehmen speichern."    elif intent == "display.configure":        from ..config import number        brightness = number(args["brightness"], 0, 100)        if (            type(args["brightness"]) is not int            or args["mode"] not in {"automatic", "manual", "off"}            or args["face"] not in FACES        ):            raise ValueError("Ungültige Displayeinstellung.")        await core.esp.command(            "BRIGHTNESS", 0 if args["mode"] == "off" else int(brightness)        )        (            core.expressions.brightness,            core.expressions.mode,            core.expressions.manual_face,        ) = int(brightness), args["mode"], args["face"]        core.expressions.applied_brightness = (            0 if args["mode"] == "off" else int(brightness)        )        core.expressions.last = None        reply = "Displaymodus und Helligkeitsvorgabe übernommen."    elif intent == "calibration.apply":        from ..calibration import validate_limits        if args["confirm"] is not True or not core.config["motion"]["calibrated"]:            raise ValueError(                "Bestätigte Ausgangskalibrierung und ausdrückliche Bestätigung erforderlich."            )        limits = validate_limits(            {axis: args[axis] for axis in ("pan", "tilt")}, core.hardware_limits        )        await core.motion.stop()        if core.settings.path:            core.settings.atomic(                core.settings.path.with_name("safe_limits.json"), limits            )        core.config["motion"].update(limits)        reply = (            "Softwaregrenzen dauerhaft gespeichert."            if core.settings.path            else "Softwaregrenzen für diese Sitzung übernommen."        ) + " Bewegung bleibt gestoppt; Home bewusst anfordern."    elif intent == "stop":        core.audio.spotify.cancel_login()        core.expressions.reset()        core.activities.games.clear()        core.people.cancel()        core.cancel_epoch += 1        core.followups.clear()        core.pending.clear()        core.power_pending.clear()        data = await core.motion.stop()        await core.audio.stop()        reply = "Lokale Aktionen gestoppt."        if not data["hardware_acknowledged"]:            reply += " Hardware-Stopp konnte nicht bestätigt werden."            status = "partial"    elif intent.startswith("motion."):        if intent == "motion.home":            data = await core.motion.home()        elif intent == "motion.configure":            data = await core.motion.configure(args["speed"], args["acceleration"])        elif intent == "motion.sequence":            data = await core.motion.sequence(args["name"])        elif intent == "motion.profile":            data = await core.motion.profile(**args)        elif intent == "motion.set":            data = await core.motion.move(args["pan"], args["tilt"])        elif intent == "motion.relative":            data = await core.motion.relative(args["axis"], args["delta"])        status = "acknowledged"        reply = (            "Simulierte Zielposition übernommen."            if core.esp.simulated            else "Zielposition angenommen; Istposition nicht gemessen."        )    elif intent == "display.face":        if not isinstance(args["face"], str) or args["face"] not in FACES:            raise ValueError("Nicht unterstützter Gesichtsausdruck.")        await core.esp.command("FACE", args["face"])        core.expressions.manual_face = args["face"]        core.expressions.set("manual", args["face"], 80, 8)        status = "acknowledged"        reply = (            "Gesichtsausdruck simuliert."            if core.esp.simulated            else "Displaybefehl angenommen."        )    elif intent == "camera.enable":        if core.privacy:            raise ValueError(                "Privatsphäre aktiv. Zuerst bewusst in der Bedienoberfläche aufheben."            )        await core.camera.start()        reply = "Kamera gestartet."    elif intent == "camera.disable":        await core.camera.stop()        reply = "Kamera und Tracking ausgeschaltet."    elif intent == "tracking.enable":        core.motion.check()        if core.people.job and core.people.job["state"] in {            "WAIT_CONSENT",            "CAPTURING",        }:            raise ValueError("Tracking bleibt während der Gesichtsanmeldung pausiert.")        if not core.camera.online or core.motion.pan is None:            raise ValueError(                "Tracking benötigt Kamera und eine bewusst angeforderte Sollposition."            )        core.motion.tracking, core.motion.stopped = True, False        reply = "Tracking aktiviert."    elif intent == "tracking.disable":        core.motion.tracking = False        await core.motion.stop()        if core.config["behavior"]["social_gaze"] and core.camera.online:            await core.motion.home()        reply = "Tracking deaktiviert."    elif intent == "privacy.enable":        core.audio.spotify.cancel_login()        core.expressions.reset()        core.people.suspend()        core.cancel_epoch += 1        core.privacy = True        await core.camera.stop()        await core.motion.stop()        await core.audio.stop()        reply = "Privatsphäre aktiviert. Mikrofonzugriff und Kamera sind gesperrt."    elif intent == "privacy.disable":        core.privacy = False        reply = "Privatsphäre aufgehoben. Kamera und Mikrofon bleiben bis zum bewussten Start aus."    elif intent == "notes.add":        data = {"id": core.store.note(args["text"])}        reply = "Notiz lokal gespeichert."    elif intent == "notes.list":        data = {"notes": core.store.notes()}        reply = (            "; ".join(n["text"] for n in data["notes"]) or "Keine Notizen gespeichert."        )    elif intent == "notes.delete":        if not isinstance(args["id"], str) or not isinstance(            args["confirmation_token"], str        ):            raise ValueError("Ungültige Löschbestätigung.")        pending = core.pending.get(session)        if (            not pending            or pending[0] < time.monotonic()            or pending[1] != args["id"]            or pending[2] != args["confirmation_token"]        ):            raise ValueError("Keine passende, gültige Löschbestätigung.")        core.pending.pop(session, None)        if not core.store.delete_note(args["id"]):            raise ValueError("Notiz nicht gefunden.")        reply = "Die bestätigte Notiz wurde gelöscht."    elif intent == "timer.start":        data = {"id": core.store.timer(args["seconds"])}        reply = "Timer lokal gespeichert und gestartet."    elif intent == "timer.status":        data = {"timers": core.store.timers()}        reply = (            "; ".join(                f"{round(t['remaining_s'])} Sekunden, {t['state']}"                for t in data["timers"]            )            or "Kein aktiver Timer."        )    elif intent == "timer.action":        if args["action"] not in {"pause", "resume", "cancel"} or not isinstance(            args["id"], str        ):            raise ValueError("Ungültige Timeraktion.")        if not core.store.timer_action(args["id"], args["action"]):            raise ValueError(                "Timer nicht gefunden oder Aktion passt nicht zum Zustand."            )        reply = "Timeraktion gespeichert."    elif intent.startswith("people."):        if intent == "people.list":            data = {"people": core.people.profiles()}            reply = (                ", ".join(p["name"] for p in data["people"])                or "Keine Personenprofile gespeichert."            )        elif intent == "people.status":            data = core.people.status()            job = data["enrollment"]            from ..people import GUIDANCE            reply = (                (                    f"Anmeldung: {job['state']}, {job.get('accepted', 0)} von {job.get('target', 0)} Ansichten. "                    + GUIDANCE.get(job.get("pose"), "")                )                if job["state"] != "IDLE"                else "Keine Gesichtsanmeldung aktiv."            )        elif intent == "people.liveness.request":            data = core.people.request_liveness()            direction = {                "left": "nach links",                "right": "nach rechts",                "front": "gerade zur Kamera",            }.get(data.get("next"), "zur Kamera")            reply = "Lebendprüfung gestartet. Bitte schaue " + direction + "."        elif intent == "people.enroll.request":            core.pending.pop(session, None)            await core.motion.stop()            data = core.people.request(args["name"], session, args["store_images"])            reply, status = data["message"], "confirmation_required"        elif intent == "people.enroll.confirm":            data = core.people.consent(session, args["token"], args["consent"])            reply = data["message"]        elif intent == "people.enroll.cancel":            core.people.cancel()            reply = "Gesichtsanmeldung abgebrochen. Temporäre Daten verworfen."        elif intent == "people.update":            core.people.update(args["id"], args["name"], args["info"], args["notes"])            data, reply = (                {"people": core.people.profiles()},                "Vorhandenes Personenprofil aktualisiert.",            )        elif intent == "people.delete":            core.people.delete(args["id"], args["confirm"])            data, reply = (                {"people": core.people.profiles()},                "Profil, aktive Bilder, Merkmale und Profilnotizen gelöscht. SQLite-/externe Backups separat beachten.",            )        elif intent == "people.fact.add":            data = {                "id": core.people.add_fact(                    args["id"], args["topic"], args["text"], args["greeting"]                )            }            reply = "Ausdrücklich mitgeteilte Profilinformation lokal gespeichert."        elif intent == "people.facts":            if not isinstance(args["id"], str):                raise ValueError("Personen-ID erforderlich.")            data = {"facts": core.people.facts(args["id"])}            reply = (                "; ".join(f["text"] for f in data["facts"])                or "Keine zusätzlichen Profilinformationen gespeichert."            )        else:            raise ValueError("Nicht unterstützte Personenaktion.")    elif intent == "calibration.auto":        raise ValueError(            "Automatische mechanische Kalibrierung gesperrt: Es ist kein bestätigter Positions-/Endsensor mit Treiber konfiguriert. Ich fahre nicht blind gegen Anschläge. Bitte Sensorik und Mechanik zuerst festlegen."        )    elif intent == "calibration.status":        data = {            "calibrated": core.config["motion"]["calibrated"],            "limits": core.config["motion"],            "automatic_available": False,            "feedback_sensor": None,        }        reply = (            "Bestätigte Grenzen sind hinterlegt."            if data["calibrated"]            else "Die Mechanik ist noch nicht kalibriert."        )        reply += " Automatische Ermittlung benötigt passende Rückmeldesensoren."    elif intent == "behavior.gaze":        if type(args["enabled"]) is not bool:            raise ValueError("Boolesche Blickfreigabe erforderlich.")        core.config["behavior"]["social_gaze"] = args["enabled"]        if not args["enabled"]:            core.motion.social_until = 0        reply = "Gelegentliche Aufmerksamkeitsblicke " + (            "aktiviert. Kamera und Home müssen freigegeben sein."            if args["enabled"]            else "deaktiviert."        )    elif intent == "game.start":        reply = core.activities.game(args["kind"], session)    elif intent == "game.cancel":        reply = core.activities.game("cancel", session)    elif intent == "stopwatch.action":        data = core.activities.stopwatch(args["action"], session)        reply = f"Stoppuhr: {data['elapsed_seconds']} Sekunden."    elif intent == "alarm.add":        data = {"id": core.activities.alarm_add(**args)}        reply = f"Wecker für {args['hour']:02d}:{args['minute']:02d} gespeichert."    elif intent == "alarm.list":        data = {"alarms": core.activities.alarms()}        reply = (            "; ".join(                f"Wecker {i + 1}: {a['hour']:02d}:{a['minute']:02d}, {'aktiv' if a['enabled'] else 'aus'}"                for i, a in enumerate(data["alarms"])            )            or "Keine Wecker gespeichert."        )    elif intent == "alarm.change":        core.activities.alarm_change(args["id"], args["action"])        reply = "Wecker geändert."    elif intent == "alarm.snooze":        from ..config import number        seconds = number(args["seconds"], 60, 3600)        if not core.last_alarm_at or time.monotonic() - core.last_alarm_at > 600:            raise ValueError(                "Kein vor kurzem ausgelöster Wecker zum Schlummern vorhanden."            )        data = {"id": core.store.timer(seconds, "Wecker-Schlummern")}        core.last_alarm_at = 0        reply = "Wecker verschoben."    elif intent == "reminder.add":        data = {"id": core.activities.reminder_add(**args)}        reply = f"Erinnerung für {args['hour']:02d}:{args['minute']:02d} gespeichert."    elif intent == "reminder.list":        data = {"reminders": core.activities.reminders()}        reply = (            "; ".join(                f"{item['hour']:02d}:{item['minute']:02d}: {item['text']}"                for item in data["reminders"]            )            or "Keine Erinnerungen gespeichert."        )    elif intent == "reminder.change":        core.activities.reminder_change(args["id"], args["action"])        reply = "Erinnerung geändert."    elif intent == "camera.configure":        from ..config import number        deadzone = number(args["deadzone"], 0, 0.4)        gain = number(args["gain"], 0.1, 5)        core.config["camera"].update(deadzone=deadzone, gain=gain)        data = {"deadzone": deadzone, "gain": gain}        reply = "Tracking-Empfindlichkeit für diese Sitzung übernommen."    elif intent == "audio.configure":        from ..config import number        volume = number(args["speech_volume"], 0, 100)        rate = number(args["speech_rate"], 0.5, 1.5)        music = number(args["music_volume"], 0, 100)        if (            type(args["speech_volume"]) is not int            or type(args["music_volume"]) is not int        ):            raise ValueError("Lautstärke muss ein ganzzahliger Prozentwert sein.")        await core.audio.set_volume(int(music))        core.audio.speech_volume, core.audio.speech_rate = int(volume), rate        reply = "Sprach- und Musikeinstellungen für diese Sitzung übernommen."    elif intent == "audio.settings":        data = core.audio.speech_settings(**args)        reply = "Sprachlautstärke und Sprechtempo angepasst."    elif intent == "audio.stop":        await core.audio.stop()        reply = "Audioausgabe gestoppt."    elif intent == "audio.test":        if not core.audio.available:            raise ValueError("Lokale Piper-Sprachausgabe ist nicht eingerichtet.")        if not await core.audio.speak(            "Hallo, hier spricht Rovo. Dies ist der lokale Sprachtest."        ):            raise ValueError("Lokaler Sprachtest konnte nicht abgeschlossen werden.")        reply = "Lokaler Sprachtest abgeschlossen."    elif intent.startswith("music."):        if intent == "music.play":            await core.audio.play(args["path"], core.media_root)        elif intent == "music.spotify":            data = await core.audio.play_spotify(args["query"])        elif intent == "music.spotify.search":            data = {                "items": await core.audio.spotify.search(args["query"], args["kind"])            }        elif intent == "music.spotify.play_uri":            await core.audio.stop_music()            data = await core.audio.spotify.play_uri(args["uri"])            core.audio.music_state = "PLAYING"        elif intent == "music.spotify.queue":            await core.audio.spotify.enqueue(args["uri"])        elif intent == "music.spotify.shuffle":            await core.audio.spotify.shuffle(args["enabled"])        elif intent == "music.adjust":            from ..config import number            delta = number(args["delta"], -100, 100)            await core.audio.set_volume(                int(max(0, min(100, core.audio.volume + delta)))            )        elif intent == "music.pause":            await core.audio.pause(True)        elif intent == "music.resume":            await core.audio.pause(False)        elif intent == "music.stop":            await core.audio.stop_music()        elif intent == "music.volume":            await core.audio.set_volume(args["value"])        reply = "Musikbefehl ausgeführt."    else:        raise ValueError("Nicht registrierte Aktion.")    return data, reply, status